/* v1.6.0 Social Pack */
#bpPassBtn{background:linear-gradient(#ffc96c,#ef9e1a)!important;box-shadow:0 4px 0 #c57e0d!important}
#bpFriendsBtn{background:linear-gradient(#77d8a7,#38a469)!important;box-shadow:0 4px 0 #2b8452!important}
#bpRankBtn{background:linear-gradient(#82a5ff,#4d74ea)!important;box-shadow:0 4px 0 #3958bc!important}
