#bpPassModal,#bpFriendsModal,#bpRankModal,#bpSkinModal{position:fixed;inset:0;z-index:5360;display:none;align-items:center;justify-content:center;padding:10px;background:rgba(10,24,52,.82);backdrop-filter:blur(5px)}
