.bpPackScreen{width:min(96vw,520px);max-height:94dvh;overflow-y:auto;background:linear-gradient(160deg,#fff,#ecf5ff);border-radius:22px;box-shadow:0 18px 50px #08152b77;padding:15px;color:#28385d}
.bpPackHead{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}.bpPackHead h2{margin:0;font-size:20px}
