// --- v1.6.0 Social Pack ---
const PASS_KEY='blockpop_event_pass_v1',FRIENDS_KEY='blockpop_friends_v1',RANK_KEY='blockpop_rank_v1',SKIN_KEY='blockpop_skin_v1';
const bpPassModal=document.getElementById('bpPassModal'),bpFriendsModal=document.getElementById('bpFriendsModal'),bpRankModal=document.getElementById('bpRankModal'),bpSkinModal=document.getElementById('bpSkinModal');
const PASS_MISSIONS=[
 {id:'score',label:'スコアを120獲得',target:120,reward:30,xp:18,field:'score'},
 {id:'lines',label:'ラインを3本消す',target:3,reward:35,xp:20,field:'lines'},
 {id:'placed',label:'ブロックを20個置く',target:20,reward:25,xp:16,field:'placed'}
];
const PASS_REWARDS=[
 {level:1,coins:20,label:'はじめのごほうび'},
 {level:2,coins:30,label:'スピードアップ支援'},
 {level:3,coins:40,label:'イベント参加賞'},
 {level:4,coins:55,label:'フレンド交流ボーナス'},
 {level:5,coins:75,label:'ランク開幕パック'},
 {level:6,coins:95,label:'プレミアスキン支援'}
];
const SKIN_PALETTES={
 classic:[['#6fa2ff','#3f72ec'],['#ff9a78','#f16855'],['#ffd35b','#f1aa2e'],['#75dfa9','#43bb80'],['#ad8cff','#825fe2'],['#61d1e9','#32a8cb'],['#ff7aa8','#e95087']],
 candy:[['#8cc8ff','#4b88ff'],['#ffb1a2','#ff6f6f'],['#ffe28a','#ffba39'],['#9df2c0','#4fd48c'],['#d0adff','#9a74ff'],['#8be9ff','#43c5f1'],['#ffb5d6','#ff69a8']],
 neon:[['#7bf3ff','#00b8ff'],['#ffa37b','#ff5d2d'],['#fff27a','#ffca18'],['#7cffaf','#13d86c'],['#d08cff','#9c3dff'],['#8ce4ff','#25b7ff'],['#ff9fd5','#ff3f93']],
 crystal:[['#cde4ff','#80b4ff'],['#ffd1bf','#ff9f7e'],['#fff1b9','#ffd05c'],['#c2f5d9','#7ed6a7'],['#e2d6ff','#b192ff'],['#c2f4ff','#7bd6ee'],['#ffd0e9','#ff94c4']],
 retro:[['#7ca7ff','#5670d6'],['#ffa089','#d96b53'],['#ead35c','#c8a02b'],['#82d39d','#4ba56d'],['#b093f0','#735ac8'],['#73c5d7','#3a8fa2'],['#ef89af','#c85c81']]
};
let bpPassState=bpLoad(PASS_KEY,{level:1,xp:0,claimed:{},daily:{date:'',score:0,lines:0,placed:0,claimed:{}}});
let bpFriendsState=bpLoad(FRIENDS_KEY,{friends:[]});
let bpRankState=bpLoad(RANK_KEY,{points:0,wins:0,losses:0,streak:0,bestStreak:0});
let bpSkinName=localStorage.getItem(SKIN_KEY)||'classic';
let bpRankQueue={waiting:false,active:false};
function bpLoad(key,fallback){try{return Object.assign({},fallback,JSON.parse(localStorage.getItem(key)||'null')||{})}catch{return JSON.parse(JSON.stringify(fallback))}}
function bpSave(key,data){try{localStorage.setItem(key,JSON.stringify(data))}catch{}}
function bpToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function bpPassNeed(level){return 100+(Math.max(1,level)-1)*40}
function bpEnsurePassDay(){const t=bpToday();if(bpPassState.daily?.date!==t)bpPassState.daily={date:t,score:0,lines:0,placed:0,claimed:{}}}
function bpPassSave(){bpSave(PASS_KEY,bpPassState)}
function bpPassAddXp(amount,reason=''){amount=Math.max(0,Math.floor(amount||0));if(!amount)return;bpPassState.xp+=amount;let leveled=0;while(bpPassState.xp>=bpPassNeed(bpPassState.level)){bpPassState.xp-=bpPassNeed(bpPassState.level);bpPassState.level++;leveled++;}
 bpPassSave();if(leveled)toast('🎟️ イベントパス Lv.'+bpPassState.level+'！');if(bpPassModal.classList.contains('show'))bpRenderPass();}
function bpPassTrack(field,amount){bpEnsurePassDay();bpPassState.daily[field]=(bpPassState.daily[field]||0)+Math.max(0,amount||0);bpPassSave();if(bpPassModal.classList.contains('show'))bpRenderPass();}
function bpClaimMission(id){bpEnsurePassDay();const task=PASS_MISSIONS.find(x=>x.id===id);if(!task)return;const v=bpPassState.daily[task.field]||0;if(v<task.target||bpPassState.daily.claimed?.[id])return;bpPassState.daily.claimed[id]=1;coins+=task.reward;saveCoins();bpPassAddXp(task.xp,'mission');bpPassSave();renderShop();toast('🎁 ミッション報酬で 🪙'+task.reward);bpRenderPass();}
function bpClaimPassReward(level){if(bpPassState.level<level||bpPassState.claimed?.[level])return;const reward=PASS_REWARDS.find(x=>x.level===level);if(!reward)return;bpPassState.claimed[level]=1;coins+=reward.coins;saveCoins();bpPassSave();renderShop();toast('🎟️ Lv.'+level+'報酬 GET！');bpRenderPass();}
function bpRenderPass(){bpEnsurePassDay();document.getElementById('bpPassLevel').textContent='Lv.'+bpPassState.level;const need=bpPassNeed(bpPassState.level);document.getElementById('bpPassXpText').textContent=bpPassState.xp+' / '+need+' XP';document.getElementById('bpPassFill').style.width=Math.max(0,Math.min(100,bpPassState.xp/need*100))+'%';const missions=document.getElementById('bpPassMissions');missions.innerHTML='';PASS_MISSIONS.forEach(task=>{const cur=Math.min(task.target,bpPassState.daily[task.field]||0);const done=cur>=task.target;const claimed=!!bpPassState.daily.claimed?.[task.id];const el=document.createElement('div');el.className='bpPackItem'+(done?' bpMissionDone':'');el.innerHTML='<div class="bpPackRow"><div><div><b>'+task.label+'</b></div><div class="bpMini">進行 '+cur+' / '+task.target+' ・ 報酬 🪙'+task.reward+' + '+task.xp+'XP</div></div><button type="button" '+(done&&!claimed?'':'disabled')+'>'+ (claimed?'受取済み':'受け取る') +'</button></div>';el.querySelector('button').addEventListener('click',()=>bpClaimMission(task.id));missions.appendChild(el);});
 const rewards=document.getElementById('bpPassRewards');rewards.innerHTML='';PASS_REWARDS.forEach(r=>{const unlocked=bpPassState.level>=r.level,claimed=!!bpPassState.claimed?.[r.level];const el=document.createElement('div');el.className='bpPackItem';el.innerHTML='<div class="bpPackRow"><div><div><b>Lv.'+r.level+' '+r.label+'</b></div><div class="bpMini">報酬 🪙'+r.coins+'</div></div><button type="button" '+(unlocked&&!claimed?'':'disabled')+'>'+(claimed?'受取済み':unlocked?'受け取る':'未到達')+'</button></div>';el.querySelector('button').addEventListener('click',()=>bpClaimPassReward(r.level));rewards.appendChild(el);});}
function bpCurrentDisplayName(){return (accountSession?.nickname||accountNickname||document.getElementById('bpGuestName')?.value.trim()||'ゲスト').slice(0,16)}
function bpRenderFriends(){document.getElementById('bpFriendMe').textContent='あなた：'+bpCurrentDisplayName();const list=document.getElementById('bpFriendsList');list.innerHTML='';const arr=bpFriendsState.friends||[];if(!arr.length){list.innerHTML='<div class="bpPackItem">まだフレンドがいないよ。ユーザー名を追加してみよう！</div>';return;}arr.forEach((f,idx)=>{const card=document.createElement('div');card.className='bpPackItem';card.innerHTML='<div class="bpPackRow"><div><div class="bpFriendName">'+bpEscape(f.name)+'</div><div class="bpMini">'+bpEscape(f.note||'メモなし')+'</div></div><button type="button">削除</button></div><div class="bpPackRow" style="margin-top:8px"><button type="button" class="secondary">名前をコピー</button><button type="button" class="secondary">共有対戦へ</button></div>';const btns=card.querySelectorAll('button');btns[0].addEventListener('click',()=>{bpFriendsState.friends.splice(idx,1);bpSave(FRIENDS_KEY,bpFriendsState);bpRenderFriends();});btns[1].addEventListener('click',async()=>{try{await navigator.clipboard.writeText(f.name);toast('📋 ユーザー名をコピー！')}catch{toast('コピーできなかったよ')}});btns[2].addEventListener('click',()=>{bpFriendsModal.classList.remove('show');showShared();});list.appendChild(card);});}
function bpEscape(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function bpAddFriend(){const name=document.getElementById('bpFriendNameInput').value.trim().slice(0,20);const note=document.getElementById('bpFriendNoteInput').value.trim().slice(0,24);if(!name){toast('フレンド名を入力してね');return;}if((bpFriendsState.friends||[]).some(f=>f.name===name)){toast('そのフレンドは登録済み！');return;}bpFriendsState.friends.push({name,note,addedAt:Date.now()});bpSave(FRIENDS_KEY,bpFriendsState);document.getElementById('bpFriendNameInput').value='';document.getElementById('bpFriendNoteInput').value='';bpRenderFriends();toast('👥 '+name+' を登録したよ');}
const BP_RANKS=[['BRONZE',0],['SILVER',120],['GOLD',260],['PLATINUM',430],['DIAMOND',650],['MASTER',900]];
function bpRankName(points){let name='BRONZE';for(const [n,p] of BP_RANKS)if(points>=p)name=n;return name}
function bpRankNext(points){for(const [n,p] of BP_RANKS)if(points<p)return [n,p];return ['MAX',points]}
function bpRenderRank(){document.getElementById('bpRankName').textContent=bpRankName(bpRankState.points);document.getElementById('bpRankPoints').textContent=bpRankState.points+' RP';document.getElementById('bpRankSummary').textContent='勝利 '+bpRankState.wins+' / 敗北 '+bpRankState.losses+' / 連勝 '+bpRankState.streak+'（最高 '+bpRankState.bestStreak+'）';const table=document.getElementById('bpRankTable');table.innerHTML='';BP_RANKS.forEach(([name,need],i)=>{const next=BP_RANKS[i+1]?.[1];const row=document.createElement('div');row.className='bpPackItem';row.innerHTML='<b>'+name+'</b><div class="bpMini">'+need+' RP'+(next?' 〜 '+(next-1)+' RP':' 以上')+'</div>';table.appendChild(row);});}
function bpApplyRankResult(result){if(result==='win'){bpRankState.wins++;bpRankState.streak++;bpRankState.bestStreak=Math.max(bpRankState.bestStreak,bpRankState.streak);bpRankState.points+=28+Math.min(12,bpRankState.streak*2);toast('🏆 ランク勝利！ RPアップ');}
 else if(result==='lose'){bpRankState.losses++;bpRankState.streak=0;bpRankState.points=Math.max(0,bpRankState.points-18);toast('🎮 ランク敗北… RPダウン');}
 else {bpRankState.points+=4;toast('🤝 引き分け！ 少しRPアップ');}
 bpSave(RANK_KEY,bpRankState);bpRenderRank();}
function bpStartRankMatch(){bpRankQueue.waiting=true;bpRankQueue.active=false;bpRankModal.classList.remove('show');showShared();
 const command={type:'shared_queue',name:bpCurrentDisplayName(),playerId:playerRandomId()};
 if(sharedWs&&sharedWs.readyState===WebSocket.CONNECTING){
  const connectingWs=sharedWs;
  connectingWs.addEventListener('open',()=>{if(sharedWs===connectingWs)sendShared(command)},{once:true});
 }else sharedConnect(command);
 sharedMessage('🏆 ランクマッチの相手を探しているよ…');}
function bpResetRank(){if(!confirm('ランク記録をリセットする？'))return;bpRankState={points:0,wins:0,losses:0,streak:0,bestStreak:0};bpSave(RANK_KEY,bpRankState);bpRenderRank();}
const __bpColorCSS=colorCSS;
colorCSS=function(pair){
 if(Array.isArray(pair)){
  for(const palette of Object.values(SKIN_PALETTES)){
   const idx=palette.findIndex(x=>x[0]===pair[0]&&x[1]===pair[1]);
   if(idx>=0)return __bpColorCSS((SKIN_PALETTES[bpSkinName]||SKIN_PALETTES.classic)[idx]);
  }
 }
 return __bpColorCSS(pair);
};
function bpApplySkin(name){const pal=SKIN_PALETTES[name]||SKIN_PALETTES.classic;for(let i=0;i<Math.min(COLORS.length,pal.length);i++){COLORS[i][0]=pal[i][0];COLORS[i][1]=pal[i][1];}
 bpSkinName=name;try{localStorage.setItem(SKIN_KEY,name)}catch{};renderBoard();renderPieces();if(typeof sharedDraw==='function')sharedDraw();bpRenderSkin();toast('🎨 スキンを '+name+' に変更！');}
function bpRenderSkin(){const grid=document.getElementById('bpSkinGrid');grid.innerHTML='';Object.entries(SKIN_PALETTES).forEach(([name,pal])=>{const card=document.createElement('div');card.className='bpSkinOption';card.innerHTML='<b>'+name.toUpperCase()+'</b><div class="bpSkinSwatches"></div><button type="button" '+(bpSkinName===name?'disabled':'')+'>'+(bpSkinName===name?'使用中':'このスキンを使う')+'</button>';const sw=card.querySelector('.bpSkinSwatches');pal.forEach(c=>{const i=document.createElement('i');i.style.background='linear-gradient(145deg,'+c[0]+','+c[1]+')';sw.appendChild(i)});card.querySelector('button').addEventListener('click',()=>bpApplySkin(name));grid.appendChild(card);});}
// wrap score / clear / place handlers for event pass
const __bpUpdateScore=updateScore;updateScore=function(){const before=Number(scoreEl.textContent)||0;__bpUpdateScore();const after=Number(scoreEl.textContent)||0;if(after>before){const delta=after-before;bpPassTrack('score',delta);bpPassAddXp(Math.max(1,Math.floor(delta/25)));}};
const __bpSoundClear=soundClear;soundClear=function(lines){bpPassTrack('lines',lines||0);bpPassAddXp((lines||0)*6);return __bpSoundClear(lines)};
const __bpPlacePiece=placePiece;placePiece=function(index,row,col){let p=currentPieces[index],blocks=0;if(p&&p.shape)for(let r=0;r<p.shape.length;r++)for(let c=0;c<p.shape[r].length;c++)if(p.shape[r][c])blocks++;const out=__bpPlacePiece(index,row,col);if(blocks){bpPassTrack('placed',blocks);bpPassAddXp(Math.max(1,Math.floor(blocks/2)));}return out};
// hook ranked shared battle results
const __bpSharedReceive=sharedReceive;sharedReceive=function(m){__bpSharedReceive(m);if(m.type==='shared_state'&&bpRankQueue.waiting&&m.state?.status==='playing')bpRankQueue.active=true; if(m.type==='shared_finished'&&bpRankQueue.active){bpRankQueue.waiting=false;bpRankQueue.active=false;const winner=m.winner;if(winner===null)bpApplyRankResult('draw');else bpApplyRankResult(winner===sharedMySlot?'win':'lose');} if(m.type==='shared_left'||m.type==='shared_error'){if(/終了|無効/.test(String(m.message||''))){bpRankQueue.waiting=false;bpRankQueue.active=false;}}};
// UI events
function bpOpen(modal,render){modal.classList.add('show');render&&render()}
document.getElementById('bpPassBtn').addEventListener('click',()=>bpOpen(bpPassModal,bpRenderPass));
document.getElementById('bpFriendsBtn').addEventListener('click',()=>bpOpen(bpFriendsModal,bpRenderFriends));
document.getElementById('bpRankBtn').addEventListener('click',()=>bpOpen(bpRankModal,bpRenderRank));
document.getElementById('bpSkinBtn').addEventListener('click',()=>bpOpen(bpSkinModal,bpRenderSkin));
document.getElementById('bpPassClose').addEventListener('click',()=>bpPassModal.classList.remove('show'));
document.getElementById('bpFriendsClose').addEventListener('click',()=>bpFriendsModal.classList.remove('show'));
document.getElementById('bpRankClose').addEventListener('click',()=>bpRankModal.classList.remove('show'));
document.getElementById('bpSkinClose').addEventListener('click',()=>bpSkinModal.classList.remove('show'));
document.getElementById('bpFriendAdd').addEventListener('click',bpAddFriend);
document.getElementById('bpFriendInviteShared').addEventListener('click',()=>{bpFriendsModal.classList.remove('show');showShared()});
document.getElementById('bpRankStart').addEventListener('click',bpStartRankMatch);
document.getElementById('bpRankReset').addEventListener('click',bpResetRank);
['bpSharedLeave','bpSharedCreate','bpSharedJoin','bpSharedQuick'].forEach(id=>document.getElementById(id).addEventListener('click',()=>{bpRankQueue.waiting=false;bpRankQueue.active=false},{capture:true}));
[bpPassModal,bpFriendsModal,bpRankModal,bpSkinModal].forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show')}));
// initial render/apply
bpEnsurePassDay();bpApplySkin(bpSkinName);bpRenderPass();bpRenderFriends();bpRenderRank();bpRenderSkin();
// --- End v1.6.0 Social Pack ---

